211				uid,
212				creator_id,
213				memo_id,
214				storage_type,
215				reference,
216				payload
217			FROM attachment
218			WHERE creator_id = `+deleteUserPlaceholder(1), []any{userID}, seen, &attachments); err != nil {
219			return nil, err
220		}
