78		"image/jpg":  true,
79		"image/gif":  true,
80		"image/webp": true,
81		"image/heic": true,
82		"image/heif": true,
83	}
84	
85	// SupportedThumbnailMimeTypes is the exported list of thumbnail-supported MIME types.
86	var SupportedThumbnailMimeTypes = []string{
87		"image/png",
88		"image/jpeg",
89		"image/jpg",
90		"image/heic",
91		"image/heif",
92		"image/webp",
93	}
